类*/ infotp.TYPE_12 ORG_ASSET_TYPE5,/*原资产五级分类*/ infotp.TYPE_6 ORG_ASSET_TYPE_EX, addq.IS_FIN_LICENCE IS_FIN_LICENCE, addq.city buy_place,/*发行人/融资人所属地区*/ null ASSET_TYPE3,/*资产二级分类细分类*/ null PBC_ASSET_TYPE1,/*人行资产一级分类*/ null PBC_ASSET_TYPE2,/*人行产二级分类*/ null PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE /*交易所基金类型*/ FROM REP_ASSET_BANK_DEPOSIT DETAIL left JOIN REP_ASSET_DEPT ASSET on detail.REP_FINPROD_ID = ASSET.REP_FINPROD_ID left join fin_product info on info.FINPROD_ID=detail.REP_FINPROD_ID left join FIN_PRODUCT_TYPE infotp on nvl(info.P_FINPROD_ID,asset.REP_FINPROD_ID)=infotp.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER=addq.CUSTOMER_ID left join mst_customer_info customerinfo on info.FINANCIER=customerinfo.CUSTOMER_ID left join REP_ASSET_OTHER ASSETOTHER on ASSETOTHER.REP_FINPROD_ID=info.FINPROD_ID WHERE 1 =1 and nvl(info.IS_CHL,'N') = 'N' and ASSET.IS_REP_TARGET = 'Y' /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( NVL(asset.UPDATE_TIME,asset.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(infotp.UPDATE_TIME,infotp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*债券资产报送信息*/ UNION ALL SELECT null ASSET_UUID, asset.FINPROD_MARKET_ID asset_code, null ASSET_TYPE, asset.REP_ASSET_TYPE ASSET_TYPE2, asset.REP_CCY CCY, asset.REP_TRADE_MARKET TRADE_MARKET, null VDATE, null MDATE, null DISCOUNT_YIELD, null ASSET_YIELD, null BASIS, null AMT, null BANK_NAME, null IS_STRUCT, null TARGET_TYPE, null TARGET, detail.SEC_ID ASSET_ID, asset.REP_FINPROD_NAME ASSET_NAME, detail.REP_SECTYPE CHB_SECTYPE, detail.REP_ISSUE_MODE ISSUE_MODE, null PARTY_GRADE,
