)t where t.rk = '1' )bestRatingZt on bestRatingZt.OCODE = info.ISSUER WHERE 1 =1 and nvl(info.IS_CHL,'N') = 'N' and ASSET.IS_REP_TARGET = 'Y' and fpd.finprod_id is null /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( NVL(asset.UPDATE_TIME,asset.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(infotp.UPDATE_TIME,infotp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*拆放同业及买入返售报送信息、负债(同业拆入/卖出回购)报送信息*/ UNION ALL SELECT null ASSET_UUID, asset.FINPROD_MARKET_ID asset_code, null ASSET_TYPE, asset.REP_ASSET_TYPE ASSET_TYPE2, asset.REP_CCY CCY, asset.REP_TRADE_MARKET TRADE_MARKET, detail.REP_VDATE VDATE, detail.REP_MDATE MDATE, null DISCOUNT_YIELD, detail.REP_RATE_YEAR ASSET_YIELD, detail.REP_BASIS BASIS, null AMT, null BANK_NAME, null IS_STRUCT, null TARGET_TYPE, null TARGET, null ASSET_ID, asset.REP_FINPROD_NAME ASSET_NAME, null CHB_SECTYPE, null ISSUE_MODE, null PARTY_GRADE, null INSTIT_SIZE, null PARTY_TYPE1, null PARTY_TYPE3, null PARTY_TYPE2, null INDUSTRY, null INDUSTRY_LEVEL2, null REGIST_ORG, null REGISTORG_COMMENT, -- decode(infotp.TYPE_6,'D01',DETAIL.REP_TRADE_TARGET,tradeproduct.COUNTER_ID) RIVAL_PARTY,---同业借款对手方取REP_ASSET_INTER_LEND.REP_TRADE_TARGET nvl(tradeproduct.COUNTER_ID,mcp.COUNTER_ID) RIVAL_PARTY,/*同业借款的对手方取标的的存款机构*/ detail.REP_TARGET_TYPE TARGET_TYPE1, detail.REP_TARGET_AMT TARGET_AMT, null COUNTRY_AREA, null PROFIT_TYPE, null IS_RESALE, null TERM_DATE, null RATE_FLAG, null INTPAY_CYCLE, null REPAY_CMT, null BASIS_TYPE, null FLOAT_FACTOR, null SPREAD_RATE, null FINANCIE, null FIN_ORG_CODE, null FCR_GRADE_IN, null FCR_GRADE_OUT, null FINANCIER_TYPE1, null FINANCIER_TYPE2, null FINANCIER_TYPE3, null FINANCE_PROJ, null INDUSTRY1, null INDUSTRY_LEVEL2_TYPE, null PRO_INDUSTRY, null PRO_INDUSTRY_LEVEL2, null INDUSTRY_FLAG, 