L INCOME_RATIO, /*固定收益部分所占比例*/ NULL DER_INSTR_RATIO, /*衍生金融工具所占比例*/ NULL DER_INSTR_INV_TYPE, /*衍生金融工具具体投资方式*/ NULL DER_INSTR_TARGET, /*衍生金融工具挂钩标的资产*/ NULL ACCT_MODE, /*利息结算方式*/ NULL SPECIAL_CMT1, /*含权情况说明*/ NULL MAX_YIELD, /*结构性票据最高收益率*/ NULL MIN_YIELD, /*结构性票据最低收益率*/ NULL BASIC_PRICE, /*挂钩标的资产基准价格*/ NULL REG_DATE_PRICE, /*挂钩标的资产登记日价格*/ NULL TRADE_FEE, /*交易费*/ NULL PARTY_CODE, /*资管计划发起人机构编码*/ NULL CHECK_CODE, /*资管计划登记编码*/ NULL MANAGER_ID, /*管理人*/ NULL TRUSTEE_ID, /*托管人*/ NULL TRU_ACT_TYPE, /*资金实际投向*/ NULL INVEST_TYPE, /*资金运用方式*/ NULL CAP_USE_INDU, /*资金运用行业一级分类*/ NULL PLAN_SDATE, /*资管计划成立日期*/ NULL PLAN_EDATE, /*资管计划终止日期*/ NULL PRO_PROPERTY, /*资管计划属性/委外投资属性*/ NULL MAX_RATE, /*最高预期收益率*/ NULL MIN_RATE, /*最低预期收益率*/ NULL DEBT_SCALE, /*负债规模*/ NULL BUY_STRUCT, /*购买结构*/ NULL MANAGE_TYPE, /*管理方式*/ NULL IS_CTRL_BOTTOM, /*是否掌控计划底层资产详情*/ NULL MGR_FEE_RATE, /*管理费率*/ NULL TRU_FEE_RATE, /*托管费率*/ NULL TRADE_FEE_RATE, /*交易相关合计费率*/ NULL AGENCY_FEE_RATE, /*中介服务机构合计费率*/ NULL OTHER_FEE_RATE, /*其他合计费率*/ NULL ASSET_VALUE, /*资产价值*/ NULL REGIST_ORG1, /*登记备案机构*/ NULL MNG_ORG_NAME, /*基金管理机构名称*/ NULL TRU_ORG_NAME, /*基金托管机构名称*/ NULL FUND_INVEST_ASSET,/*基金投资资产*/ NULL IN_ASSET_TYPE, /*行内资产类别*/ NULL IN_ASSET_TYPE_CMM, /*行内资产类别说明*/ NULL REMARK, /*备注*/ NULL IS_UNDER_ASSET, /*是否底层资产*/ NULL IS_GOVERN_FUND, /*是否属于政府投资基金*/ NULL GOVERN_INVEST_FUND, /*政府投资基金投向*/ NULL FUND_ENPE_NAME, /*基金公司名称*/ NULL TRUSTEE, /*受托人*/ 'E' STATUS, /*数据状态*/ FTP.CREATE_USER CREATE_USER, /*创建人*/ FTP.CREATE_TIME CREATE_TIME, /*创建时间*/ FTP.UPDATE_USER UPDATE_USER, /*更新人*/ GREATEST(NVL(NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')), NVL(NVL(MSP.UPDATE_TIME,MSP.CREATE_TIME),TO_DATE('1900-01-01','YYYY-MM-DD')) ) UPDATE_TIME, /*更新时间*/ FTP.CREATE_DEPT DEPT_CODE, /*部门代码*/ NULL ORG_CODE, /*机构代码*/ NULL DATA_SOURCE, /*数据来源*/ NULL PRIVATEFUND_FLAG, /*是否投向投向“金融资产投资公司或其附属机构"发行的私募股权投资基金*/ NULL PRIVATEPRD_FLAG, /*是否投向金融资产投资公司发行的私募资产管理产品*/ null PRIVATE_FLAG, NULL BONDTOSTOCK_FLAG, /*是否投向“市场化债转股相关产品的部分”*/ NULL PPPFLAG, /*公共PPP*/ SYSDATE STATUS_DATE, /*数据日期*/ NULL CAP_USE_INDU_LEVEL2, /*资金运用行业二级分类*/ NULL ISSUE_PARTY_NAME, /*发行机构*/ NULL SEC_CREDIT_GRADE_TYPE, /*债券信用评级*/ NULL SEC_MAIN_GRADE, /*主体评级*/ DECODE(MSP.P_TYPE_ONE,'C01','01','C02','01','C03','01','C04','01','C05','01', 'C06', '02', '01') BLN_AREA, /*境内外*/ addq.INDUSTRY INDUSTRY_PBC,/*融资人所属行业一级分类（人行）*/ NULL CUSTOMER_OBJ_TYPE, /*客户主体类型*/ FPTYPE.TYPE_8 ORG_ASSET_TYPE1,/*原资产一级分类*/ FPTYPE.TYPE_9 ORG_ASSET_TYPE2,/*原资产二级分类*/ FPTYPE.TYPE_10 ORG_ASSET_TYPE3,/*原资产三级分类*/ FPTYPE.TYPE_11 ORG_ASSET_TYPE4,/*原资产四级分类*/ FPTYPE.TYPE_12 ORG_ASSET_TYPE5,/*原资产五级分类*/ FPTYPE.TYPE_6 ORG_ASSET_TYPE_EX, addq.IS_FIN_LICENCE IS_FIN_LICENCE, NULL BUY_PLACE, /*发行人/融资人所属地区*/ NULL ASSET_TYPE3, /*资产二级分类细分类*/ NULL PBC_ASSET_TYPE1, /*人行资产一级分类*/ NULL PBC_ASSET_TYPE2, /*人行产二级分类*/ NULL PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE /*交易所基金类型*/ FROM FIN_TRADE_PRODUCT FTP LEFT JOIN MST_COUNTER_PARTY MSP ON FTP.COUNTER_ID = MSP.COUNTER_ID LEFT JOIN FIN_PRODUCT_TYPE FPTYPE ON FTP.FINPROD_ID = FPTYPE.FINPROD_ID LEFT JOIN FIN_PRODUCT INFO ON INFO.FINPROD_ID=FTP.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER=addq.CUSTOMER_ID left join REP_ASSET_OTHER ASSETOTHER on ASSETOTHER.REP_FINPROD_ID=info.FINPROD_ID WHERE FTP.FINPROD_TYPE2 IN ('F11', 'F12', 'F13', 'F14', 'F29', 'F30','F35') AND NVL(INFO.IS_CHL,'N') = 'N' /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( NVL(FTP.UPDATE_TIME,FTP.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(MSP.UPDATE_TIME,MSP.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} OR NVL(FPTYPE.UPDATE_TIME,FPTYPE.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) UNION ALL /*拆借、质押式回购、买断式回购*/ SELECT null ASSET_UUID, fp.finprod_id asset_code, '02' ASSET_TYPE, decode(fp.finprod_type2, 'F02', '1902', 'F04', '1902', 'F03', '1108', 'F05', '1108', 'F08', '1901', '1107') ASSET_TYPE2, fp.CCY CCY, nvl(fp.trade_market, '17') TRADE_MARKET, fp.vdate VDATE, fp.mdate MDATE, null DISCOUNT_YIELD, fp.int_rate * 100 ASSET_YIELD, DECODE(fp.BASIS, 'A/365', '03', '02') BASIS, null AMT, null BANK_NAME, null IS_STRUCT, null TARGET_TYPE, null TARGET, null ASSET_ID, null ASSET_NAME, null CHB_SECTYPE, null ISSUE_MODE, null PARTY_GRADE, null INSTIT_SIZE, null PARTY_TYPE1, null PARTY_TYPE3, null PARTY_TYPE2, null INDUSTRY, null INDUSTRY_LEVEL2, null REGIST_ORG, null REGISTORG_COMMENT, fp.counter_id RIVAL_PARTY, case when fp.finprod_type2 in ('F02', 'F03', 'F04', 'F05') then '01' else null end as TARGET_TYPE1, case when fp.finprod_type2 in ('F02', 'F03', 'F04', 'F05') then (select nvl(sum(dp.pledge_number) * 100, fp.prin) from FIN_DEAL_PLEDGE dp where dp.finprod_id = fp.finprod_id) else null end as TARGET_AMT, null COUNTRY_AREA, null PROFIT_TYPE, null IS_RESALE, null TERM_DATE, null RATE_FLAG, null INTPAY_CYCLE, null REPAY_CMT, null BASIS_TYPE, null FLOAT_FACTOR, null SPREAD_RATE, null FINANCIE, null FIN_ORG_CODE, null FCR_GRADE_IN, null FCR_GRADE_OUT, null FINANCIER_TYPE1, null FINANCIER_TYPE2, null FINANCIER_TYPE3, null FINANCE_PROJ, null INDUSTRY1, null INDUSTRY_LEVEL2_TYPE, null PRO_INDUSTRY, null PRO_INDUSTRY_LEVEL2, null INDUSTRY_FLAG, null MONIT_TYPE, null MON_TYPE_COMM, null GUA_TYPE, null GUA_TYPE_REMARK, null FINANCIER_GRADE, null IN_GRADE, null OUT_GRADE, null CHOSE, null CONDITION_CMM, null FIN_AREA, null TOTAL_FEE_RATE, null IS_RIGHT, null NOTSTAND_SEC_TYPE, null NOTSTAND_SEC_NUM, null REMAIN_TERM, null MAX_REMAIN_TERM, null MIN_REMAIN_TERM, null SHARES_TYPE, null INDUSTRY_SHARES, null INDUSTRY_SHARES2, null INVEST_STAGE, null SHARES_TYPE1, null SHARES_TYPE2, null SHARES_TYPE3, null IS_PLEDGE, null NOM_CAPI, NULL TARGET_TYPE3, null ISSUE_PARTY_ID, null TERM_MONTH, null GUARANTEE_CMT, null SPECIAL_CMT, null CONTRACT_NAME, null INCOME_RATIO, null DER_INSTR_RATIO, null DER_INSTR_INV_TYPE, null DER_INSTR_TARGET, null ACCT_MODE, null SPECIAL_CMT1, null MAX_YIELD, null MIN_YIELD, null BASIC_PRICE, null REG_DATE_PRICE, null TRADE_FEE, null PARTY_CODE, null CHECK_CODE, null MANAGER_ID, null TRUSTEE_ID, null TRU_ACT_TYPE, null INVEST_TYPE, null CAP_USE_INDU, null PLAN_SDATE, null PLAN_EDATE, null PRO_PROPERTY, null MAX_RATE, null MIN_RATE, null DEBT_SCALE, null BUY_STRUCT, null MANAGE_TYPE, null IS_CTRL_BOTTOM, null MGR_FEE_RATE, null TRU_FEE_RATE, null TRADE_FEE_RATE, null AGENCY_FEE_RATE, null OTHER_FEE_RATE, null ASSET_VALUE, null REGIST_ORG1, null MNG_ORG_NAME, null TRU_ORG_NAME, null FUND_INVEST_ASSET, null IN_ASSET_TYPE, null IN_ASSET_TYPE_CMM, null REMARK, null IS_UNDER_ASSET, null IS_GOVERN_FUND, null GOVERN_INVEST_FUND, null FUND_ENPE_NAME, NULL TRUSTEE, DECODE(NVL(td.TRADE_id, 'null'), 'null', 'E', 'D') STATUS, fp.CREATE_USER CREATE_USER, fp.CREATE_TIME CREATE_TIME, fp.UPDATE_USER UPDATE_USER, greatest(nvl(NVL(fp.UPDATE_TIME, fp.CREATE_TIME), to_date('1900-01-01', 'yyyy-MM-dd')), nvl(NVL(info.UPDATE_TIME, info.CREATE_TIME), to_date('1900-01-01', 'yyyy-MM-dd')), nvl(NVL(infotp.UPDATE_TIME, infotp.CREATE_TIME), to_date('1900-01-01', 'yyyy-MM-dd')), nvl(NVL(customerinfo.UPDATE_TIME, customerinfo.CREATE_TIME), to_date('1900-01-01', 'yyyy-MM-dd')), nvl(NVL(addq.UPDATE_TIME, addq.CREATE_TIME), to_date('1900-01-01', 'yyyy-MM-dd')), nvl(NVL(td.UPDATE_TIME, td.CREATE_TIME), to_date('1900-01-01', 'yyyy-MM-dd')), nvl(NVL(counterparty.UPDATE_TIME,counterparty.CREATE_TIME), to_date('1900-01-01','yyyy-MM-dd'))) UPDATE_TIME, null DEPT_CODE, NULL ORG_CODE, 'bszg' data_source, /*数据来源*/ null PRIVATEFUND_FLAG, null privateprd_flag, null PRIVATE_FLAG, null bondtostock_flag, NULL PPPFLAG, sysdate status_date, NULL CAP_USE_INDU_LEVEL2, NULL ISSUE_PARTY_NAME, /*发行机构*/ null SEC_CREDIT_GRADE_TYPE, NULL SEC_MAIN_GRADE, /**/ '01' BLN_AREA, /*境内外*/ addq.INDUSTRY INDUSTRY_PBC, /*融资人所属行业一级分类（人行）*/ decode(customerinfo.CUSTOMER_TYPE, '02', 'C01', nvl(addq.CUSTOMER_OBJ_TYPE, 'C03')) CUSTOMER_OBJ_TYPE, /*客户主体类型*/ infotp.TYPE_8 ORG_ASSET_TYPE1,/*原资产一级分类*/ infotp.TYPE_9 ORG_ASSET_TYPE2,/*原资产二级分类*/ infotp.TYPE_10 ORG_ASSET_TYPE3,/*原资产三级分类*/ infotp.TYPE_11 ORG_ASSET_TYPE4,/*原资产四级分类*/ infotp.TYPE_12 ORG_ASSET_TYPE5,/*原资产五级分类*/ infotp.TYPE_6 ORG_ASSET_TYPE_EX, addq.IS_FIN_LICENCE IS_FIN_LICENCE, addq.city buy_place, /*发行人/融资人所属地区*/ null ASSET_TYPE3, /*资产二级分类细分类*/ null PBC_ASSET_TYPE1, /*人行资产一级分类*/ null PBC_ASSET_TYPE2, /*人行产二级分类*/ null PBC_ASSET_TYPE3,/*人行产三级分类*/ null TRM_FUND_TYPE /*交易所基金类型*/ FROM fin_trade_product fp left join fin_product info on info.FINPROD_ID = fp.FINPROD_ID left join FIN_PRODUCT_TYPE infotp on fp.FINPROD_ID = infotp.FINPROD_ID left join MST_CUSTOMER_INFO_ADD addq on info.FINANCIER = addq.CUSTOMER_ID left join mst_customer_info customerinfo on info.FINANCIER = customerinfo.CUSTOMER_ID left join trd_product_deal td on Fp.FINPROD_ID = tD.P_TRADE_ID left join REP_ASSET_OTHER ASSETOTHER on ASSETOTHER.REP_FINPROD_ID=info.FINPROD_ID left join mst_counter_party counterparty on counterparty.COUNTER_ID = fp.COUNTER_ID WHERE 1 = 1 and fp.branch = 0 and fp.finprod_type2 in ('F02', 'F03', 'F04', 'F05') and (fp.data_source is null or fp.data_source!='01') /*根据创建时间、更新时间和接口接入时间接入数据*/ AND( NVL(fp.UPDATE_TIME,fp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(info.UPDATE_TIME,info.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(infotp.UPDATE_TIME,infotp.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(customerinfo.UPDATE_TIME,customerinfo.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(td.UPDATE_TIME,td.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(addq.UPDATE_TIME,addq.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP} or NVL(counterparty.UPDATE_TIME,counterparty.CREATE_TIME) > #{interfDate,jdbcType=TIMESTAMP}) /*拆借、质押式回购、买断式回购*/
